"use client";

import {
  createContext,
  useContext,
  useMemo,
  useRef,
  useState,
  useCallback,
  type ReactNode,
  type RefObject,
} from "react";
import type { Anchor, Direction } from "./offsets";

export type MorphAnimationConfig = {
  triggerBlur: number;
  contentBlur: number;
  contentDelay: number;
};

export type MorphSize = {
  width: number;
  height: number;
  borderRadius: number;
};

export type MorphMenuContextValue = {
  open: boolean;
  setOpen: (open: boolean) => void;
  direction: Direction;
  anchor: Anchor;
  visualDuration: number;
  bounce: number;
  animationConfig: MorphAnimationConfig;
  shellRef: RefObject<HTMLDivElement | null>;
  contentRef: RefObject<HTMLDivElement | null>;
  isOpenAnimationCompleteRef: RefObject<boolean>;
  /** Live shell size for glass — updated every morph frame. */
  subscribeMorphSize: (listener: (size: MorphSize) => void) => () => void;
  reportMorphSize: (size: MorphSize) => void;
  getMorphSize: () => MorphSize | null;
  /** True while width/height spring is running. */
  morphing: boolean;
  setMorphing: (morphing: boolean) => void;
};

const MorphMenuContext = createContext<MorphMenuContextValue | null>(null);

export function useMorphMenu() {
  const ctx = useContext(MorphMenuContext);
  if (!ctx) {
    throw new Error("MorphMenu components must be used within MorphMenu.Root");
  }
  return ctx;
}

/** Optional — GlassShellBackdrop uses this when nested in a MorphMenu. */
export function useMorphMenuOptional() {
  return useContext(MorphMenuContext);
}

const defaultAnimationConfig: MorphAnimationConfig = {
  triggerBlur: 8,
  contentBlur: 10,
  contentDelay: 0,
};

type ProviderProps = {
  children: ReactNode;
  open: boolean;
  setOpen: (open: boolean) => void;
  direction: Direction;
  anchor: Anchor;
  visualDuration: number;
  bounce: number;
  animationConfig?: Partial<MorphAnimationConfig>;
};

export function MorphMenuProvider({
  children,
  open,
  setOpen,
  direction,
  anchor,
  visualDuration,
  bounce,
  animationConfig: animationConfigProp,
}: ProviderProps) {
  const shellRef = useRef<HTMLDivElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);
  const isOpenAnimationCompleteRef = useRef(false);
  const listenersRef = useRef(new Set<(size: MorphSize) => void>());
  const lastSizeRef = useRef<MorphSize | null>(null);
  const [morphing, setMorphing] = useState(false);

  const requestOpen = useCallback(
    (next: boolean) => {
      if (next === open) return;
      // Set the interaction lock in the same event as the open-state change.
      // Container's layout effect remains as a fallback for externally
      // controlled changes that bypass this function.
      isOpenAnimationCompleteRef.current = false;
      setMorphing(true);
      setOpen(next);
    },
    [open, setOpen],
  );

  const animationConfig = useMemo(
    () => ({ ...defaultAnimationConfig, ...animationConfigProp }),
    [animationConfigProp],
  );

  const reportMorphSize = useCallback((size: MorphSize) => {
    lastSizeRef.current = size;
    for (const listener of listenersRef.current) {
      listener(size);
    }
  }, []);

  const subscribeMorphSize = useCallback((listener: (size: MorphSize) => void) => {
    listenersRef.current.add(listener);
    if (lastSizeRef.current) listener(lastSizeRef.current);
    return () => {
      listenersRef.current.delete(listener);
    };
  }, []);

  const getMorphSize = useCallback(() => lastSizeRef.current, []);

  const value = useMemo<MorphMenuContextValue>(
    () => ({
      open,
      setOpen: requestOpen,
      direction,
      anchor,
      visualDuration,
      bounce,
      animationConfig,
      shellRef,
      contentRef,
      isOpenAnimationCompleteRef,
      subscribeMorphSize,
      reportMorphSize,
      getMorphSize,
      morphing,
      setMorphing,
    }),
    [
      open,
      requestOpen,
      direction,
      anchor,
      visualDuration,
      bounce,
      animationConfig,
      subscribeMorphSize,
      reportMorphSize,
      getMorphSize,
      morphing,
    ],
  );

  return <MorphMenuContext.Provider value={value}>{children}</MorphMenuContext.Provider>;
}

import type { CSSProperties } from "react";

export type Direction = "top" | "bottom" | "left" | "right";
export type Anchor = "start" | "center" | "end";

/** Anchor the absolute shell to the closed-slot corner for the open direction. */
export function shellAnchorStyle(direction: Direction): CSSProperties {
  const style: CSSProperties = { position: "absolute" };
  switch (direction) {
    case "top":
      style.bottom = 0;
      style.left = 0;
      break;
    case "bottom":
      style.top = 0;
      style.left = 0;
      break;
    case "left":
      style.right = 0;
      style.bottom = 0;
      break;
    case "right":
      style.left = 0;
      style.bottom = 0;
      break;
  }
  return style;
}

/** Shift so `anchor: end|center` keeps the closed pill edge aligned while width/height grow. */
export function anchorShift(
  direction: Direction,
  anchor: Anchor,
  menuWidth: number,
  menuHeight: number,
  buttonWidth: number,
  buttonHeight: number,
): { x: number; y: number } {
  if (anchor === "start") return { x: 0, y: 0 };
  const factor = anchor === "center" ? 0.5 : 1;
  if (direction === "top" || direction === "bottom") {
    return { x: -(menuWidth - buttonWidth) * factor, y: 0 };
  }
  return { x: 0, y: (menuHeight - buttonHeight) * factor };
}

/** Gap between closed pill and open panel along the open direction. */
export function directionOffset(
  direction: Direction,
  offsetPx: number,
): { x: number; y: number } {
  switch (direction) {
    case "top":
      return { y: -offsetPx, x: 0 };
    case "bottom":
      return { y: offsetPx, x: 0 };
    case "left":
      return { x: -offsetPx, y: 0 };
    case "right":
      return { x: offsetPx, y: 0 };
  }
}

export function contentEnterOffset(
  direction: Direction,
  distance: number,
): { x: number; y: number } {
  switch (direction) {
    case "top":
      return { x: 0, y: distance };
    case "bottom":
      return { x: 0, y: -distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
  }
}

"use client";

import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type AnimationPlaybackControls,
} from "motion/react";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { useMorphMenu } from "./context";
import {
  anchorShift,
  directionOffset,
  shellAnchorStyle,
} from "./offsets";
import { IOS_POINTER_CANCEL_ATTRACTION_EVENT } from "../ios-pointer";

type ButtonSize = number | { width: number; height: number };

type ContainerProps = {
  children: ReactNode;
  backdrop?: ReactNode;
  buttonSize?: ButtonSize;
  menuWidth?: number;
  menuRadius?: number;
  buttonRadius?: number;
  /** Distance the open panel is offset from the trigger along `direction`. */
  offset?: number;
  className?: string;
  style?: CSSProperties;
};

function resolveButtonSize(buttonSize: ButtonSize) {
  if (typeof buttonSize === "number") {
    return { width: buttonSize, height: buttonSize };
  }
  return buttonSize;
}

export function Container({
  children,
  backdrop,
  buttonSize = 48,
  menuWidth = 200,
  menuRadius = 24,
  buttonRadius,
  offset,
  className = "",
  style,
}: ContainerProps) {
  const {
    open,
    direction,
    anchor,
    visualDuration,
    bounce,
    shellRef,
    contentRef,
    reportMorphSize,
    setMorphing,
    morphing,
    isOpenAnimationCompleteRef,
  } = useMorphMenu();

  const reduced = useReducedMotion();
  const { width: buttonWidth, height: buttonHeight } = resolveButtonSize(buttonSize);
  const closedRadius = buttonRadius ?? Math.min(buttonWidth, buttonHeight) / 2;
  const gap = offset ?? buttonHeight * 0.75;

  // Persist across close — clearing this used to stop/restart the close spring.
  const measuredHeightRef = useRef(buttonHeight);
  const [openTargetHeight, setOpenTargetHeight] = useState<number | null>(null);
  const animGenRef = useRef(0);
  const prevOpenRef = useRef(open);

  // Flip morphing synchronously when `open` changes so Content/Trigger don't
  // unmount for a frame before the spring effect runs (that gap killed glass).
  useLayoutEffect(() => {
    if (prevOpenRef.current === open) return;
    prevOpenRef.current = open;
    setMorphing(true);
    shellRef.current?.dispatchEvent(
      new Event(IOS_POINTER_CANCEL_ATTRACTION_EVENT, { bubbles: true }),
    );
  }, [open, setMorphing, shellRef]);

  useLayoutEffect(() => {
    if (!open) return;
    const el = contentRef.current;
    const next =
      el && el.offsetHeight > 1 ? el.offsetHeight : measuredHeightRef.current;
    measuredHeightRef.current = next;
    setOpenTargetHeight(next);
  }, [open, contentRef]);

  const widthMv = useMotionValue(buttonWidth);
  const heightMv = useMotionValue(buttonHeight);
  const radiusMv = useMotionValue(closedRadius);
  const xMv = useMotionValue(0);
  const yMv = useMotionValue(0);
  const progressMv = useMotionValue(open ? 1 : 0);

  const controlsRef = useRef<AnimationPlaybackControls[]>([]);

  useEffect(() => {
    if (open && openTargetHeight === null) return;

    if (open) {
      isOpenAnimationCompleteRef.current = false;
    }

    const menuHeight = openTargetHeight ?? measuredHeightRef.current;
    const shift = anchorShift(
      direction,
      anchor,
      menuWidth,
      menuHeight,
      buttonWidth,
      buttonHeight,
    );
    const gapXY = directionOffset(direction, gap);
    const openX = gapXY.x + shift.x;
    const openY = gapXY.y + shift.y;

    const spring = reduced
      ? { type: "spring" as const, stiffness: 1000, damping: 100 }
      : { type: "spring" as const, visualDuration, bounce };

    controlsRef.current.forEach((c) => c.stop());
    const animGen = ++animGenRef.current;

    const targetW = open ? menuWidth : buttonWidth;
    const targetH = open ? menuHeight : buttonHeight;
    const targetR = open ? menuRadius : closedRadius;
    const targetX = open ? openX : 0;
    const targetY = open ? openY : 0;

    // Mount / prop churn often re-runs this effect while already at rest.
    // Flipping morphing true then would unmount the trigger and leave an
    // opacity-0 Content layer eating taps until finished resolves — which
    // some mobile WebKits never do for a no-op spring.
    const alreadyAtRest =
      Math.abs(widthMv.get() - targetW) < 0.5 &&
      Math.abs(heightMv.get() - targetH) < 0.5 &&
      Math.abs(radiusMv.get() - targetR) < 0.5 &&
      Math.abs(xMv.get() - targetX) < 0.5 &&
      Math.abs(yMv.get() - targetY) < 0.5;
    if (alreadyAtRest) {
      progressMv.set(open ? 1 : 0);
      setMorphing(false);
      reportMorphSize({
        width: widthMv.get(),
        height: heightMv.get(),
        borderRadius: radiusMv.get(),
      });
      return;
    }

    let cancelled = false;
    let controls: AnimationPlaybackControls[] = [];
    let unsubscribeProgress = () => {};
    const start = async () => {
      if (cancelled || animGen !== animGenRef.current) return;

      setMorphing(true);
      const applyProgress = (progress: number) => {
        const mix = (closed: number, opened: number) =>
          closed + (opened - closed) * progress;
        const width = mix(buttonWidth, menuWidth);
        const height = mix(buttonHeight, menuHeight);
        const radius = mix(closedRadius, menuRadius);
        widthMv.set(width);
        heightMv.set(height);
        radiusMv.set(radius);
        xMv.set(openX * progress);
        yMv.set(openY * progress);
        reportMorphSize({ width, height, borderRadius: radius });
      };
      applyProgress(progressMv.get());
      unsubscribeProgress = progressMv.on("change", applyProgress);
      controls = [animate(progressMv, open ? 1 : 0, spring)];
      controlsRef.current = controls;

      await Promise.all(controls.map((c) => c.finished));
      if (animGen !== animGenRef.current) return;
      setMorphing(false);
      reportMorphSize({
        width: widthMv.get(),
        height: heightMv.get(),
        borderRadius: radiusMv.get(),
      });
    };
    void start();

    return () => {
      cancelled = true;
      unsubscribeProgress();
      controls.forEach((c) => c.stop());
    };
  }, [
    open,
    openTargetHeight,
    menuWidth,
    menuRadius,
    closedRadius,
    buttonWidth,
    buttonHeight,
    direction,
    anchor,
    gap,
    visualDuration,
    bounce,
    reduced,
    widthMv,
    heightMv,
    radiusMv,
    xMv,
    yMv,
    progressMv,
    setMorphing,
    reportMorphSize,
    isOpenAnimationCompleteRef,
  ]);

  const anchorStyle = shellAnchorStyle(direction);

  return (
    <div style={{ position: "relative", width: buttonWidth, height: buttonHeight }}>
      <motion.div
        ref={shellRef}
        data-ios-pointer-attraction-disabled={open || morphing ? "" : undefined}
        className={className}
        style={{
          ...anchorStyle,
          width: widthMv,
          height: heightMv,
          borderRadius: radiusMv,
          x: xMv,
          y: yMv,
          overflow: "hidden",
          cursor: open ? "default" : "pointer",
          // Keep elevated while morphing — dropping to auto the instant `open`
          // flips false lets neighbors cover the shell and kills refraction.
          zIndex: open || morphing ? 50 : "auto",
          willChange: "transform",
          ...style,
        }}
      >
        {backdrop}
        <div
          className="relative size-full"
          style={
            {
              width: open || morphing ? menuWidth : undefined,
              position: open || morphing ? "absolute" : "relative",
              ...(open || morphing
                ? {
                    left:
                      direction === "right"
                        ? 0
                        : direction === "left"
                          ? "auto"
                          : anchor === "start"
                            ? 0
                            : anchor === "center"
                              ? "50%"
                              : "auto",
                    right:
                      direction === "left"
                        ? 0
                        : direction === "right"
                          ? "auto"
                          : anchor === "end"
                            ? 0
                            : "auto",
                    translate:
                      (direction === "top" || direction === "bottom") && anchor === "center"
                        ? "-50% 0"
                        : undefined,
                  }
                : {}),
              "--morph-menu-closed-width": `${buttonWidth}px`,
              "--morph-menu-closed-height": `${buttonHeight}px`,
            } as CSSProperties
          }
        >
          {children}
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { CSSProperties, PointerEvent as ReactPointerEvent, ReactNode } from "react";
import { useMorphMenu } from "./context";

type OverlayProps = {
  className?: string;
  style?: CSSProperties;
  onClick?: () => void;
};

export function Overlay({ className = "", style, onClick }: OverlayProps) {
  const { open, setOpen, visualDuration, bounce } = useMorphMenu();
  const reduced = useReducedMotion();
  const transition = reduced
    ? { type: "spring" as const, stiffness: 1000, damping: 100 }
    : { type: "spring" as const, visualDuration, bounce };

  return (
    <AnimatePresence>
      {open ? (
        <motion.div
          key="morph-overlay"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={transition}
          className={className}
          style={{
            position: "fixed",
            top: 0,
            right: 0,
            left: 0,
            // Keep clear of Safari's bottom "chin" sampling zone (iOS 26+):
            // a full-bleed fixed layer there retints the toolbar and hides
            // page content that was visible through the liquid-glass chrome.
            bottom: "max(48px, env(safe-area-inset-bottom, 0px))",
            ...style,
          }}
          aria-hidden
          onClick={(e) => {
            e.preventDefault();
            if (onClick) onClick();
            else setOpen(false);
          }}
        />
      ) : null}
    </AnimatePresence>
  );
}

type TriggerProps = {
  children: ReactNode;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
  /** Accessible name when Trigger is the sole control (e.g. hamburger). */
  "aria-label"?: string;
};

export function Trigger({
  children,
  disabled = false,
  className = "",
  style,
  "aria-label": ariaLabel,
}: TriggerProps) {
  const {
    open,
    setOpen,
    direction,
    anchor,
    visualDuration,
    animationConfig,
  } = useMorphMenu();
  const reduced = useReducedMotion();
  const triggerBlur = reduced ? "blur(0px)" : `blur(${animationConfig.triggerBlur}px)`;
  const transition = reduced
    ? { duration: 0 }
    : {
        opacity: {
          duration: visualDuration * 0.75,
          ease: [0.4, 0, 0.2, 1] as const,
        },
        filter: {
          duration: visualDuration * 0.9,
          ease: [0.4, 0, 0.2, 1] as const,
        },
      };

  const closedFrameStyle: CSSProperties =
    direction === "top" || direction === "bottom"
      ? {
          top: direction === "bottom" ? 0 : "auto",
          bottom: direction === "top" ? 0 : "auto",
          left: anchor === "start" ? 0 : anchor === "center" ? "50%" : "auto",
          right: anchor === "end" ? 0 : "auto",
          translate: anchor === "center" ? "-50% 0" : undefined,
          width: "var(--morph-menu-closed-width)",
          height: "var(--morph-menu-closed-height)",
        }
      : {
          top: "50%",
          bottom: "auto",
          left: direction === "right" ? 0 : "auto",
          right: direction === "left" ? 0 : "auto",
          translate: "0 -50%",
          width: "var(--morph-menu-closed-width)",
          height: "var(--morph-menu-closed-height)",
        };

  return (
    <motion.button
      data-ios-pointer-target={disabled || open ? undefined : ""}
      type="button"
      disabled={disabled}
      tabIndex={open ? -1 : undefined}
      aria-label={ariaLabel}
      aria-expanded={open}
      aria-haspopup="menu"
      initial={false}
      animate={{
        opacity: open ? 0 : 1,
        filter: open ? triggerBlur : "blur(0px)",
        transition: transition,
      }}
      className={className}
      style={{
        position: "absolute",
        // The shell grows into the open panel, but the outgoing trigger must
        // retain its closed geometry and anchor. Otherwise its children are
        // re-centered into the full panel on the first expansion frame.
        ...closedFrameStyle,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        cursor: disabled ? "not-allowed" : "pointer",
        // Keep this layer mounted so it can crossfade with Content in both
        // directions, but remove it from hit testing while the menu is open.
        pointerEvents: open ? "none" : "auto",
        border: 0,
        background: "transparent",
        padding: 0,
        // Avoid 300ms tap delay / gesture ambiguity on mobile WebKit.
        touchAction: "manipulation",
        WebkitTapHighlightColor: "transparent",
        ...style,
      }}
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!disabled) setOpen(true);
      }}
      onKeyDown={(e) => {
        if (disabled) return;
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setOpen(true);
        }
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setOpen(true);
        }
      }}
    >
      {children}
    </motion.button>
  );
}

type ContentProps = {
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
  onAnimationComplete?: () => void;
  onPointerLeave?: () => void;
};

export function Content({
  children,
  className = "",
  style,
  onAnimationComplete,
  onPointerLeave,
}: ContentProps) {
  const {
    open,
    contentRef,
    animationConfig,
    direction,
    visualDuration,
    bounce,
    isOpenAnimationCompleteRef,
  } = useMorphMenu();
  const reduced = useReducedMotion();
  const transformTransition = reduced
    ? { duration: 0 }
    : { type: "spring" as const, visualDuration: visualDuration * 0.85, bounce };
  const contentBlur = reduced ? "blur(0px)" : `blur(${animationConfig.contentBlur}px)`;
  const contentDelay = reduced || !open ? 0 : animationConfig.contentDelay;
  const opacityTransition = reduced
    ? { duration: 0 }
    : {
        duration: visualDuration * 0.75,
        ease: [0.4, 0, 0.2, 1] as const,
        delay: contentDelay,
      };
  const blurTransition = reduced
    ? { duration: 0 }
    : {
        duration: visualDuration * 0.9,
        ease: [0.4, 0, 0.2, 1] as const,
        delay: contentDelay,
      };

  const closedOffset = (() => {
    switch (direction) {
      case "top":
        return { x: 0, y: 4 };
      case "bottom":
        return { x: 0, y: -4 };
      case "left":
        return { x: 4, y: 0 };
      case "right":
        return { x: -4, y: 0 };
    }
  })();
  return (
    <motion.div
      ref={(node) => {
        contentRef.current = node;
      }}
      role="menu"
      aria-hidden={!open}
      className={className}
      style={{
        position: "relative",
        // Keep the open content in the shell's pointer-event path while it
        // morphs so GlassShellBackdrop can light the newly revealed panel.
        // Item-level handlers and pointer attributes remain locked below until
        // the shell settles, so rows do not hover, attract, or select early.
        pointerEvents: open ? "auto" : "none",
        ...style,
      }}
      initial={false}
      animate={{
        opacity: open ? 1 : 0,
        filter: open ? "blur(0px)" : contentBlur,
        scale: open ? 1 : 0.985,
        x: open ? 0 : closedOffset.x,
        y: open ? 0 : closedOffset.y,
        transition: {
          opacity: opacityTransition,
          filter: blurTransition,
          scale: { ...transformTransition, delay: contentDelay },
          x: { ...transformTransition, delay: contentDelay },
          y: { ...transformTransition, delay: contentDelay },
        },
      }}
      onAnimationComplete={() => {
        if (open) {
          isOpenAnimationCompleteRef.current = true;
          onAnimationComplete?.();
        }
      }}
      onPointerLeave={onPointerLeave}
    >
      {children}
    </motion.div>
  );
}

type ItemProps = {
  children: ReactNode;
  onSelect?: () => void;
  onPointerEnter?: (event: ReactPointerEvent<HTMLDivElement>) => void;
  disabled?: boolean;
  closeOnSelect?: boolean;
  className?: string;
  style?: CSSProperties;
};

export function Item({
  children,
  onSelect,
  onPointerEnter,
  disabled = false,
  closeOnSelect = true,
  className = "",
  style,
}: ItemProps) {
  const { open, setOpen, morphing, isOpenAnimationCompleteRef } = useMorphMenu();
  const canRespondToHover = () =>
    !morphing && isOpenAnimationCompleteRef.current && !disabled;

  return (
    <div
      role="menuitem"
      data-ios-pointer-hit-area={disabled || !open || morphing ? undefined : ""}
      aria-disabled={disabled || undefined}
      data-disabled={disabled || undefined}
      style={{
        cursor: disabled ? "not-allowed" : "pointer",
        userSelect: "none",
        touchAction: "manipulation",
        WebkitTapHighlightColor: "transparent",
        ...style,
      }}
      onClick={(e) => {
        e.preventDefault();
        if (disabled || !open || morphing) return;
        onSelect?.();
        if (closeOnSelect) setOpen(false);
      }}
      onMouseEnter={() => {
        if (!canRespondToHover()) return;
      }}
      onPointerEnter={(event) => {
        if (!canRespondToHover()) return;
        onPointerEnter?.(event);
      }}
      // The menu can expand underneath an already-stationary pointer. In that
      // case no pointerenter is fired for the newly mounted first item, while
      // pointermove still is. Let the owner initialize its shared hover fill.
      onPointerMove={(event) => {
        if (!canRespondToHover()) return;
        onPointerEnter?.(event);
      }}
    >
      <div
        data-ios-pointer-visual={disabled ? undefined : ""}
        className={`pointer-events-none ${className}`}
      >
        {children}
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import {
  MorphMenuProvider,
  useMorphMenu,
  type MorphAnimationConfig,
} from "./context";
import type { Anchor, Direction } from "./offsets";

type RootProps = {
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  direction?: Direction;
  anchor?: Anchor;
  visualDuration?: number;
  bounce?: number;
  animationConfig?: Partial<MorphAnimationConfig>;
  closeOnClickOutside?: boolean;
  closeOnEscape?: boolean;
};

function useControllableOpen(
  controlled: boolean | undefined,
  defaultOpen: boolean,
  onOpenChange?: (open: boolean) => void,
) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isControlled = controlled !== undefined;
  const open = isControlled ? controlled : uncontrolled;

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setUncontrolled(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange],
  );

  return [open, setOpen] as const;
}

function DismissListeners({
  closeOnClickOutside,
  closeOnEscape,
}: {
  closeOnClickOutside: boolean;
  closeOnEscape: boolean;
}) {
  const { open, setOpen, shellRef, contentRef } = useMorphMenu();

  useEffect(() => {
    if (!open || !closeOnEscape) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setOpen(false);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, closeOnEscape, setOpen]);

  useEffect(() => {
    if (!open || !closeOnClickOutside) return;
    // Capture-phase pointerdown so we can swallow the gesture: without a
    // fullscreen fixed overlay (avoided for iOS Safari toolbar tint), taps
    // would otherwise both dismiss and activate controls underneath.
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (shellRef.current?.contains(target)) return;
      if (contentRef.current?.contains(target)) return;
      setOpen(false);
      e.preventDefault();
      e.stopPropagation();
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [open, closeOnClickOutside, setOpen, shellRef, contentRef]);

  return null;
}

export function Root({
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  direction = "bottom",
  anchor: anchorProp = "start",
  visualDuration = 0.28,
  bounce = 0,
  animationConfig,
  closeOnClickOutside = true,
  closeOnEscape = true,
}: RootProps) {
  const anchor =
    direction === "left" || direction === "right" ? "center" : anchorProp;
  const [open, setOpen] = useControllableOpen(openProp, defaultOpen, onOpenChange);

  const handleSetOpen = useCallback(
    (next: boolean) => {
      setOpen(next);
    },
    [setOpen],
  );

  return (
    <MorphMenuProvider
      open={open}
      setOpen={handleSetOpen}
      direction={direction}
      anchor={anchor}
      visualDuration={visualDuration}
      bounce={bounce}
      animationConfig={animationConfig}
    >
      <DismissListeners
        closeOnClickOutside={closeOnClickOutside}
        closeOnEscape={closeOnEscape}
      />
      {children}
    </MorphMenuProvider>
  );
}

export { Root } from "./root";
export { Container } from "./container";
export { Overlay, Trigger, Content, Item } from "./parts";
export { useMorphMenu, useMorphMenuOptional, type MorphSize } from "./context";
export type { Direction, Anchor } from "./offsets";

import { Root } from "./root";
import { Container } from "./container";
import { Overlay, Trigger, Content, Item } from "./parts";

export const MorphMenu = {
  Root,
  Container,
  Overlay,
  Trigger,
  Content,
  Item,
};

"use client";

import { useEffect, useRef } from "react";

const MAX_ATTRACTION_PX = 5;
const ATTRACTION_CURVE_EXPONENT = 1.1;
const ATTRACTION_PROXIMITY_PX = 24;
const ATTRACTION_EDGE_RAMP_PX = 24;
const ATTRACTION_EXIT_MARGIN_PX = 16;
const TARGET_SPRING_STIFFNESS = 260;
const TARGET_SPRING_DAMPING = 29;
const TARGET_SPRING_MASS = 0.8;

// Press-drag deformation (Apple liquid-glass buttons): while the primary
// button is held, the control follows the pointer with a rubber-band that
// asymptotes at PRESS_MAX_TRAVEL_PX — so it deforms and shifts toward the
// cursor but can never be dragged away — and springs back on release. The
// jelly squish is derived from the spring-eased displacement (not raw pointer
// velocity), so it is inherently smooth and settles together with the travel.
const PRESS_MAX_TRAVEL_PX = 8; // rubber-band asymptote → can't be dragged off
// Pre-scale on the drag distance before it hits the tanh: the control lags the
// cursor from the very first pixel (resistance felt continuously) instead of
// tracking 1:1 and then slamming into the asymptote — the same "pre-tensioned
// spring" feel as the draggable glass capsules.
const PRESS_RESISTANCE = 0.55;
const PRESS_STRETCH = 0.14; // elongation along the drag axis at full travel
const PRESS_STRETCH_PERP = 0.14; // perpendicular compression (volume-conserving)
const PRESS_LIFT = 0.07; // gentle uniform "pop"/enlarge while held
const PRESS_CLICK_CANCEL_PX = 6; // travel beyond this swallows the click

export const IOS_POINTER_CANCEL_ATTRACTION_EVENT =
  "ios-pointer-cancel-attraction";

type AttractedTarget = {
  companion: HTMLElement | null;
  element: HTMLElement;
  hitArea: HTMLElement;
  exitMargin: number;
  maxAttraction: number;
  proximity: number;
  exiting: boolean;
  frame: number | null;
  lastTime: number | null;
  targetX: number;
  targetY: number;
  vx: number;
  vy: number;
  x: number;
  y: number;
  // Press-drag deformation state.
  pressing: boolean;
  pressOriginX: number;
  pressOriginY: number;
  maxTravel: number;
  press: number; // eased 0→1 press amount
  pressV: number;
  pressTarget: number; // 0 released / 1 held
};

type AttractionTarget = {
  element: HTMLElement;
  hitArea: HTMLElement;
  exitMargin: number;
  maxAttraction: number;
  proximity: number;
};

type AttractionBounds = {
  height: number;
  left: number;
  top: number;
  width: number;
};

type CompanionController = {
  element: HTMLElement;
  exiting: boolean;
  frame: number | null;
  lastTime: number | null;
  maxAttraction: number;
  proximity: number;
  pointerX: number;
  pointerY: number;
  targetX: number;
  targetY: number;
  vx: number;
  vy: number;
  x: number;
  y: number;
};

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function mapAttraction(relativePosition: number, maxAttraction: number) {
  const normalized = clamp(relativePosition, -1, 1);
  return (
    Math.sign(normalized) *
    Math.pow(Math.abs(normalized), ATTRACTION_CURVE_EXPONENT) *
    maxAttraction
  );
}

function getAttractionDepth(
  pointerX: number,
  pointerY: number,
  left: number,
  top: number,
  width: number,
  height: number,
) {
  return Math.max(
    0,
    Math.min(
      pointerX - left,
      left + width - pointerX,
      pointerY - top,
      top + height - pointerY,
    ),
  );
}

function applyAttractionEnvelope(
  x: number,
  y: number,
  insideDepth: number,
  outsideDistance: number,
  proximity: number,
) {
  // Treat the outer proximity boundary and the inside edge ramp as one
  // continuous field. At the outer boundary attraction is exactly zero; it
  // grows through the element edge and reaches full strength after the
  // pointer has travelled EDGE_RAMP_PX inside.
  const fieldDepth = proximity - outsideDistance + insideDepth;
  const rampLength = Math.max(proximity + ATTRACTION_EDGE_RAMP_PX, 1);
  const progress = clamp(fieldDepth / rampLength, 0, 1);
  const easedProgress = progress * progress * (3 - 2 * progress);
  return { x: x * easedProgress, y: y * easedProgress };
}

function getOutsideDistance(
  pointerX: number,
  pointerY: number,
  left: number,
  top: number,
  width: number,
  height: number,
) {
  const dx = Math.max(left - pointerX, 0, pointerX - (left + width));
  const dy = Math.max(top - pointerY, 0, pointerY - (top + height));
  return Math.hypot(dx, dy);
}

function getTargetNumber(element: HTMLElement, name: string, fallback: number) {
  const value = Number(element.dataset[name]);
  return Number.isFinite(value) ? value : fallback;
}

function createAttractionTarget(element: HTMLElement, hitArea = element): AttractionTarget {
  return {
    element,
    hitArea,
    exitMargin: getTargetNumber(
      hitArea,
      "iosPointerExitMargin",
      ATTRACTION_EXIT_MARGIN_PX,
    ),
    maxAttraction: getTargetNumber(
      hitArea,
      "iosPointerMaxAttraction",
      MAX_ATTRACTION_PX,
    ),
    proximity: getTargetNumber(
      hitArea,
      "iosPointerProximity",
      ATTRACTION_PROXIMITY_PX,
    ),
  };
}

function getAttractionTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return null;

  const hitArea = target.closest<HTMLElement>("[data-ios-pointer-hit-area]");
  if (hitArea) {
    const visual = hitArea.querySelector<HTMLElement>("[data-ios-pointer-visual]");
    return visual ? createAttractionTarget(visual, hitArea) : null;
  }

  const explicit = target.closest<HTMLElement>("[data-ios-pointer-target]");
  if (explicit) {
    if (explicit.matches(".site-hover-fill")) {
      return createAttractionTarget(explicit);
    }
    const element =
      explicit.closest<HTMLElement>(".glass-surface, .glass-shell") ?? explicit;
    if (element.hasAttribute("data-ios-pointer-attraction-disabled")) {
      return null;
    }
    return createAttractionTarget(element);
  }

  const interactive = target.closest<HTMLElement>(
    'a, button:not(:disabled), input[type="button"]:not(:disabled)',
  );
  if (!interactive) return null;
  if (interactive.matches(".site-hover-fill")) {
    return createAttractionTarget(interactive);
  }

  const element = interactive.closest<HTMLElement>(".glass-surface, .glass-shell");
  if (
    !element ||
    element.hasAttribute("data-ios-pointer-attraction-disabled")
  ) {
    return null;
  }
  return createAttractionTarget(element);
}

/**
 * Fine-pointer attraction: interactive controls ease toward the native cursor
 * and press-drag with a rubber-band squish. Uses the OS cursor (no custom lag
 * dot) so tracking stays 1:1.
 */
export function IOSPointer() {
  const targetRef = useRef<AttractedTarget | null>(null);

  useEffect(() => {
    const root = document.documentElement;
    if (!window.matchMedia("(pointer: fine)").matches) return;

    root.classList.add("ios-pointer-ready");

    const controllers = new Set<AttractedTarget>();
    const companionControllers = new Map<HTMLElement, CompanionController>();
    let proximityCandidatesDirty = true;
    let proximityCandidates: Array<{
      bounds: AttractionBounds;
      target: AttractionTarget;
    }> = [];

    const getBaseBounds = (target: AttractionTarget) => {
      const rect = target.hitArea.getBoundingClientRect();
      const movingController =
        target.hitArea === target.element
          ? Array.from(controllers).find(
              (controller) => controller.element === target.element,
            )
          : undefined;
      const offsetX = movingController?.x ?? 0;
      const offsetY = movingController?.y ?? 0;
      return {
        height: rect.height,
        left: rect.left - offsetX,
        top: rect.top - offsetY,
        width: rect.width,
      };
    };

    const refreshProximityCandidates = () => {
      const candidates = document.querySelectorAll<HTMLElement>(
        [
          "[data-ios-pointer-hit-area]",
          "[data-ios-pointer-target]",
          ".site-hover-fill",
          ".glass-surface a",
          ".glass-surface button:not(:disabled)",
          ".glass-shell a",
          ".glass-shell button:not(:disabled)",
        ].join(","),
      );
      const seen = new Set<HTMLElement>();
      const nextCandidates: typeof proximityCandidates = [];

      for (const candidate of candidates) {
        const target = getAttractionTarget(candidate);
        if (
          !target ||
          seen.has(target.element) ||
          !target.hitArea.isConnected ||
          target.hitArea.getClientRects().length === 0
        ) {
          continue;
        }
        seen.add(target.element);
        nextCandidates.push({ bounds: getBaseBounds(target), target });
      }

      proximityCandidates = nextCandidates;
      proximityCandidatesDirty = false;
    };

    const getProximityTarget = (pointerX: number, pointerY: number) => {
      if (proximityCandidatesDirty) refreshProximityCandidates();
      let closest: { distance: number; target: AttractionTarget } | null = null;

      for (const { bounds, target } of proximityCandidates) {
        const distance = getOutsideDistance(
          pointerX,
          pointerY,
          bounds.left,
          bounds.top,
          bounds.width,
          bounds.height,
        );
        if (distance > target.proximity) continue;
        if (!closest || distance < closest.distance) {
          closest = { distance, target };
        }
      }

      return closest?.target ?? null;
    };

    const invalidateProximityCandidates = () => {
      proximityCandidatesDirty = true;
    };
    const proximityObserver = new MutationObserver(invalidateProximityCandidates);
    proximityObserver.observe(document.body, {
      attributeFilter: [
        "data-ios-pointer-attraction-disabled",
        "data-ios-pointer-exit-margin",
        "data-ios-pointer-hit-area",
        "data-ios-pointer-max-attraction",
        "data-ios-pointer-proximity",
        "data-ios-pointer-target",
        "disabled",
      ],
      attributes: true,
      childList: true,
      subtree: true,
    });
    window.addEventListener("resize", invalidateProximityCandidates, {
      passive: true,
    });
    window.addEventListener("scroll", invalidateProximityCandidates, {
      capture: true,
      passive: true,
    });

    const finishCompanionController = (controller: CompanionController) => {
      if (controller.frame !== null) cancelAnimationFrame(controller.frame);
      controller.element.style.removeProperty("--ios-pointer-attract-x");
      controller.element.style.removeProperty("--ios-pointer-attract-y");
      controller.element.removeAttribute("data-ios-pointer-hover-active");
      companionControllers.delete(controller.element);
    };

    const tickCompanionController = (
      controller: CompanionController,
      time: number,
    ) => {
      controller.frame = null;
      const elapsed =
        controller.lastTime === null ? 1 / 60 : (time - controller.lastTime) / 1000;
      const dt = Math.min(0.032, Math.max(1 / 240, elapsed));
      controller.lastTime = time;

      if (!controller.exiting) {
        // Motion is independently moving the shared fill between menu rows.
        // Derive attraction from the fill's current visual row rather than
        // from the newly hit item's center, whose local Y flips from -1 to +1
        // at every adjacent boundary. Subtract our own translate to isolate
        // Motion's continuously animated base geometry.
        const rect = controller.element.getBoundingClientRect();
        const left = rect.left - controller.x;
        const top = rect.top - controller.y;
        const centerX = left + rect.width / 2;
        const centerY = top + rect.height / 2;
        const relativeX =
          (controller.pointerX - centerX) / Math.max(rect.width / 2, 1);
        const relativeY =
          (controller.pointerY - centerY) / Math.max(rect.height / 2, 1);
        const mappedX = mapAttraction(
          relativeX,
          controller.maxAttraction,
        );
        const mappedY = mapAttraction(
          relativeY,
          controller.maxAttraction,
        );
        const depth = getAttractionDepth(
          controller.pointerX,
          controller.pointerY,
          left,
          top,
          rect.width,
          rect.height,
        );
        const outsideDistance = getOutsideDistance(
          controller.pointerX,
          controller.pointerY,
          left,
          top,
          rect.width,
          rect.height,
        );
        const limited = applyAttractionEnvelope(
          mappedX,
          mappedY,
          depth,
          outsideDistance,
          controller.proximity,
        );
        controller.targetX = limited.x;
        controller.targetY = limited.y;
      }

      const ax =
        (-TARGET_SPRING_STIFFNESS * (controller.x - controller.targetX) -
          TARGET_SPRING_DAMPING * controller.vx) /
        TARGET_SPRING_MASS;
      const ay =
        (-TARGET_SPRING_STIFFNESS * (controller.y - controller.targetY) -
          TARGET_SPRING_DAMPING * controller.vy) /
        TARGET_SPRING_MASS;
      controller.vx += ax * dt;
      controller.vy += ay * dt;
      controller.x += controller.vx * dt;
      controller.y += controller.vy * dt;

      controller.element.style.setProperty(
        "--ios-pointer-attract-x",
        `${controller.x}px`,
      );
      controller.element.style.setProperty(
        "--ios-pointer-attract-y",
        `${controller.y}px`,
      );

      const settled =
        Math.abs(controller.x - controller.targetX) < 0.02 &&
        Math.abs(controller.y - controller.targetY) < 0.02 &&
        Math.abs(controller.vx) < 0.02 &&
        Math.abs(controller.vy) < 0.02;
      if (settled) {
        controller.x = controller.targetX;
        controller.y = controller.targetY;
        if (controller.exiting) finishCompanionController(controller);
        return;
      }

      controller.frame = requestAnimationFrame((nextTime) =>
        tickCompanionController(controller, nextTime),
      );
    };

    const startCompanionController = (controller: CompanionController) => {
      if (controller.frame !== null) return;
      controller.lastTime = null;
      controller.frame = requestAnimationFrame((time) =>
        tickCompanionController(controller, time),
      );
    };

    const getCompanionController = (element: HTMLElement) => {
      const existing = companionControllers.get(element);
      if (existing) return existing;

      const controller: CompanionController = {
        element,
        exiting: false,
        frame: null,
        lastTime: null,
        maxAttraction: MAX_ATTRACTION_PX,
        proximity: ATTRACTION_PROXIMITY_PX,
        pointerX: 0,
        pointerY: 0,
        targetX: 0,
        targetY: 0,
        vx: 0,
        vy: 0,
        x: 0,
        y: 0,
      };
      companionControllers.set(element, controller);
      return controller;
    };

    const attractCompanion = (
      element: HTMLElement,
      pointerX: number,
      pointerY: number,
      maxAttraction: number,
      proximity: number,
    ) => {
      const controller = getCompanionController(element);
      controller.exiting = false;
      controller.pointerX = pointerX;
      controller.pointerY = pointerY;
      controller.maxAttraction = maxAttraction;
      controller.proximity = proximity;
      element.setAttribute("data-ios-pointer-hover-active", "");
      startCompanionController(controller);
    };

    const releaseCompanion = (element: HTMLElement) => {
      const controller = companionControllers.get(element);
      element.removeAttribute("data-ios-pointer-hover-active");
      if (!controller) return;
      controller.exiting = true;
      controller.targetX = 0;
      controller.targetY = 0;
      startCompanionController(controller);
    };

    const finishController = (controller: AttractedTarget) => {
      if (controller.frame !== null) cancelAnimationFrame(controller.frame);
      controller.element.removeAttribute("data-ios-pointer-attracted");
      controller.element.style.removeProperty("--ios-pointer-attract-x");
      controller.element.style.removeProperty("--ios-pointer-attract-y");
      controller.element.style.removeProperty("--ios-pointer-squish-x");
      controller.element.style.removeProperty("--ios-pointer-squish-y");
      controllers.delete(controller);
      if (controllers.size === 0) root.classList.remove("ios-pointer-attracting");
    };

    const tickController = (controller: AttractedTarget, time: number) => {
      controller.frame = null;
      const elapsed = controller.lastTime === null ? 1 / 60 : (time - controller.lastTime) / 1000;
      const dt = Math.min(0.032, Math.max(1 / 240, elapsed));
      controller.lastTime = time;

      const ax =
        (-TARGET_SPRING_STIFFNESS * (controller.x - controller.targetX) -
          TARGET_SPRING_DAMPING * controller.vx) /
        TARGET_SPRING_MASS;
      const ay =
        (-TARGET_SPRING_STIFFNESS * (controller.y - controller.targetY) -
          TARGET_SPRING_DAMPING * controller.vy) /
        TARGET_SPRING_MASS;
      controller.vx += ax * dt;
      controller.vy += ay * dt;
      controller.x += controller.vx * dt;
      controller.y += controller.vy * dt;

      // Press amount rides its own spring so the push-in eases in/out.
      const pAcc =
        (-TARGET_SPRING_STIFFNESS * (controller.press - controller.pressTarget) -
          TARGET_SPRING_DAMPING * controller.pressV) /
        TARGET_SPRING_MASS;
      controller.pressV += pAcc * dt;
      controller.press += controller.pressV * dt;

      controller.element.style.setProperty("--ios-pointer-attract-x", `${controller.x}px`);
      controller.element.style.setProperty("--ios-pointer-attract-y", `${controller.y}px`);

      // Jelly squish from the eased displacement: elongate along the axis the
      // control is pulled, compress the other (volume-conserving), on top of a
      // small uniform "pop"/enlarge while held. Deriving from controller.x/y
      // (spring output) keeps it smooth — no raw-velocity spikes.
      const travelAx = Math.min(1, Math.abs(controller.x) / PRESS_MAX_TRAVEL_PX);
      const travelAy = Math.min(1, Math.abs(controller.y) / PRESS_MAX_TRAVEL_PX);
      const lift = 1 + PRESS_LIFT * controller.press;
      const squishX = lift * (1 + PRESS_STRETCH * travelAx - PRESS_STRETCH_PERP * travelAy);
      const squishY = lift * (1 + PRESS_STRETCH * travelAy - PRESS_STRETCH_PERP * travelAx);
      controller.element.style.setProperty("--ios-pointer-squish-x", `${squishX}`);
      controller.element.style.setProperty("--ios-pointer-squish-y", `${squishY}`);

      const settled =
        Math.abs(controller.x - controller.targetX) < 0.02 &&
        Math.abs(controller.y - controller.targetY) < 0.02 &&
        Math.abs(controller.vx) < 0.02 &&
        Math.abs(controller.vy) < 0.02 &&
        Math.abs(controller.press - controller.pressTarget) < 0.002 &&
        Math.abs(controller.pressV) < 0.02;
      if (settled) {
        controller.x = controller.targetX;
        controller.y = controller.targetY;
        controller.press = controller.pressTarget;
        if (controller.exiting) finishController(controller);
        return;
      }

      controller.frame = requestAnimationFrame((nextTime) =>
        tickController(controller, nextTime),
      );
    };

    const startController = (controller: AttractedTarget) => {
      if (controller.frame !== null) return;
      controller.lastTime = null;
      controller.frame = requestAnimationFrame((time) => tickController(controller, time));
    };

    const releaseController = (controller: AttractedTarget) => {
      controller.exiting = true;
      controller.targetX = 0;
      controller.targetY = 0;
      if (controller.companion) releaseCompanion(controller.companion);
      startController(controller);
    };

    const clearTarget = () => {
      const active = targetRef.current;
      if (!active) return;
      releaseController(active);
      targetRef.current = null;
    };

    const cancelAttraction = (event: Event) => {
      const active = targetRef.current;
      if (
        !(event.target instanceof HTMLElement) ||
        !active ||
        (active.element !== event.target && !event.target.contains(active.element))
      ) {
        return;
      }

      // Cancel both the active row/trigger and its shared hover fill before a
      // morph begins. Neither should keep reacting to a stationary pointer
      // while the menu geometry and content layers are animating.
      if (active.companion) {
        const companion = companionControllers.get(active.companion);
        if (companion) finishCompanionController(companion);
        else active.companion.removeAttribute("data-ios-pointer-hover-active");
      }
      finishController(active);
      targetRef.current = null;
    };

    const attractTarget = (
      {
        element,
        hitArea,
        exitMargin,
        maxAttraction,
        proximity,
      }: AttractionTarget,
      clientX: number,
      clientY: number,
    ) => {
      if (targetRef.current?.element !== element) {
        const previous = targetRef.current;
        const companion =
          element
            .closest<HTMLElement>('[role="menu"]')
            ?.querySelector<HTMLElement>(".ios-pointer-native-hover-fill") ?? null;
        const sharesCompanion = Boolean(
          previous && companion && previous.companion === companion,
        );
        clearTarget();
        if (sharesCompanion && previous) previous.companion = null;
        const returning = Array.from(controllers).find(
          (controller) => controller.element === element,
        );
        if (returning) {
          // Keep the returning item's current position so re-entry is visually
          // continuous, but discard its velocity toward rest. Otherwise a
          // quick adjacent-item reversal briefly carries the item away from
          // the pointer before the new attraction target takes over.
          if (returning.frame !== null) cancelAnimationFrame(returning.frame);
          returning.frame = null;
          returning.lastTime = null;
          returning.vx = 0;
          returning.vy = 0;
        }
        element.setAttribute("data-ios-pointer-attracted", "");
        targetRef.current = returning ?? {
          companion,
          element,
          hitArea,
          exitMargin,
          maxAttraction,
          proximity,
          exiting: false,
          frame: null,
          lastTime: null,
          targetX: 0,
          targetY: 0,
          vx: 0,
          vy: 0,
          x: 0,
          y: 0,
          pressing: false,
          pressOriginX: 0,
          pressOriginY: 0,
          maxTravel: 0,
          press: 0,
          pressV: 0,
          pressTarget: 0,
        };
        targetRef.current.companion = companion;
        targetRef.current.hitArea = hitArea;
        targetRef.current.exitMargin = exitMargin;
        targetRef.current.maxAttraction = maxAttraction;
        targetRef.current.proximity = proximity;
        targetRef.current.exiting = false;
        controllers.add(targetRef.current);
        root.classList.add("ios-pointer-attracting");
      }

      const active = targetRef.current;
      if (!active) return;

      // Menu items use a stationary wrapper for hit testing. Other controls
      // use the moving element itself, so remove its current translate.
      const rect = hitArea.getBoundingClientRect();
      const hitAreaMoves = hitArea === element;
      const centerX = rect.left + rect.width / 2 - (hitAreaMoves ? active.x : 0);
      const centerY = rect.top + rect.height / 2 - (hitAreaMoves ? active.y : 0);
      // Normalize against the target's own bounds before mapping to the fixed
      // travel distance. A wide menu item and a compact icon now feel equally
      // magnetic at the same relative cursor position.
      const relativeX = (clientX - centerX) / Math.max(rect.width / 2, 1);
      const relativeY = (clientY - centerY) / Math.max(rect.height / 2, 1);
      const mappedX = mapAttraction(relativeX, active.maxAttraction);
      const mappedY = mapAttraction(relativeY, active.maxAttraction);
      const left = rect.left - (hitAreaMoves ? active.x : 0);
      const top = rect.top - (hitAreaMoves ? active.y : 0);
      const depth = getAttractionDepth(
        clientX,
        clientY,
        left,
        top,
        rect.width,
        rect.height,
      );
      const outsideDistance = getOutsideDistance(
        clientX,
        clientY,
        left,
        top,
        rect.width,
        rect.height,
      );
      const next = applyAttractionEnvelope(
        mappedX,
        mappedY,
        depth,
        outsideDistance,
        active.proximity,
      );

      active.targetX = next.x;
      active.targetY = next.y;
      if (active.companion) {
        attractCompanion(
          active.companion,
          clientX,
          clientY,
          active.maxAttraction,
          active.proximity,
        );
      }
      startController(active);
    };

    // While the button is held, the active target follows the pointer through a
    // rubber-band that asymptotes at PRESS_MAX_TRAVEL_PX — deforms and shifts
    // toward the cursor, but is physically incapable of being dragged off.
    // Locks onto the pressed element; hover routing is bypassed.
    const updatePressDrag = (active: AttractedTarget, clientX: number, clientY: number) => {
      const dx = clientX - active.pressOriginX;
      const dy = clientY - active.pressOriginY;
      const r = Math.hypot(dx, dy);
      if (r < 1e-4) {
        active.targetX = 0;
        active.targetY = 0;
      } else {
        // Map the drag *magnitude* through the curve (asymptote is a circle of
        // radius PRESS_MAX_TRAVEL_PX, not a per-axis square), pre-scaled by
        // PRESS_RESISTANCE so travel is damped from the first pixel. Rescale
        // the clamped magnitude back onto the original direction.
        const mappedR =
          PRESS_MAX_TRAVEL_PX * Math.tanh((r * PRESS_RESISTANCE) / PRESS_MAX_TRAVEL_PX);
        const scale = mappedR / r;
        active.targetX = dx * scale;
        active.targetY = dy * scale;
      }
      active.maxTravel = Math.max(active.maxTravel, r);
      startController(active);
    };

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType !== "mouse") return;

      const pressed = targetRef.current;
      if (pressed?.pressing) {
        updatePressDrag(pressed, event.clientX, event.clientY);
        return;
      }

      let target = getAttractionTarget(event.target);
      const active = targetRef.current;
      // A MorphMenu shell grows from a compact trigger into the full panel.
      // Retaining it through the generic exit margin would make that entire
      // panel keep following the cursor after expansion.
      const canRetainActiveTarget = !active?.element.matches(".glass-shell");
      if (!target && active?.element.isConnected && canRetainActiveTarget) {
        const rect = active.hitArea.getBoundingClientRect();
        const hitAreaMoves = active.hitArea === active.element;
        const left = rect.left - (hitAreaMoves ? active.x : 0);
        const top = rect.top - (hitAreaMoves ? active.y : 0);
        const outsideDistance = getOutsideDistance(
          event.clientX,
          event.clientY,
          left,
          top,
          rect.width,
          rect.height,
        );
        const insideExitZone =
          outsideDistance <= active.proximity + active.exitMargin;
        if (insideExitZone) {
          target = {
            element: active.element,
            hitArea: active.hitArea,
            exitMargin: active.exitMargin,
            maxAttraction: active.maxAttraction,
            proximity: active.proximity,
          };
        }
      }
      if (!target) {
        target = getProximityTarget(event.clientX, event.clientY);
      }
      if (target) attractTarget(target, event.clientX, event.clientY);
      else clearTarget();
    };

    const onPointerLeave = () => {
      // A held button keeps deforming even if the cursor leaves the window;
      // only release ends it. Idle hover attraction still clears normally.
      if (targetRef.current?.pressing) return;
      clearTarget();
    };

    let suppressClick = false;

    const onPointerDown = (event: PointerEvent) => {
      if (event.pointerType !== "mouse" || event.button !== 0) return;
      const target = getAttractionTarget(event.target);
      // Phase 1: only the standalone glass pills deform on press. The nav's
      // selected fill (.site-hover-fill) is handled separately.
      if (!target || target.element.matches(".site-hover-fill")) return;

      attractTarget(target, event.clientX, event.clientY);
      const active = targetRef.current;
      if (!active) return;
      active.pressing = true;
      active.pressOriginX = event.clientX;
      active.pressOriginY = event.clientY;
      active.pressTarget = 1;
      active.maxTravel = 0;
      updatePressDrag(active, event.clientX, event.clientY);
    };

    const endPress = (event: PointerEvent) => {
      const active = targetRef.current;
      if (!active?.pressing) return;
      active.pressing = false;
      active.pressTarget = 0;
      // A meaningful drag shouldn't also fire the control's click/navigation.
      if (active.maxTravel > PRESS_CLICK_CANCEL_PX) suppressClick = true;
      // Hand back to hover routing: re-evaluate the release position so the
      // control eases from its dragged pose to the resting hover offset (or
      // clears if the pointer ended outside).
      onPointerMove(event);
    };

    const onClickCapture = (event: MouseEvent) => {
      if (!suppressClick) return;
      suppressClick = false;
      event.preventDefault();
      event.stopPropagation();
    };

    // Press-drag reads raw pointermove, not Motion's `drag` (which already
    // swallows this). Without it, the browser's native drag-and-drop hijacks
    // the gesture — an <img>/link ghost-drag starts instead of the button
    // deforming. `-webkit-user-drag: none` in CSS covers Blink/WebKit; this
    // covers Firefox (which ignores that property) and any el that slips
    // through the CSS selector scope.
    const onDragStart = (event: DragEvent) => {
      if (!(event.target instanceof Element)) return;
      if (event.target.closest("[data-ios-pointer-target], .site-hover-fill")) {
        event.preventDefault();
      }
    };

    window.addEventListener("pointermove", onPointerMove, { passive: true });
    window.addEventListener("pointerleave", onPointerLeave, { passive: true });
    window.addEventListener("pointerdown", onPointerDown, { passive: true });
    window.addEventListener("pointerup", endPress, { passive: true });
    window.addEventListener("pointercancel", endPress, { passive: true });
    window.addEventListener("click", onClickCapture, true);
    window.addEventListener("dragstart", onDragStart);
    window.addEventListener(IOS_POINTER_CANCEL_ATTRACTION_EVENT, cancelAttraction);

    return () => {
      for (const controller of controllers) finishController(controller);
      for (const controller of companionControllers.values()) {
        finishCompanionController(controller);
      }
      targetRef.current = null;
      root.classList.remove("ios-pointer-ready");
      proximityObserver.disconnect();
      window.removeEventListener("resize", invalidateProximityCandidates);
      window.removeEventListener("scroll", invalidateProximityCandidates, true);
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerleave", onPointerLeave);
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointerup", endPress);
      window.removeEventListener("pointercancel", endPress);
      window.removeEventListener("click", onClickCapture, true);
      window.removeEventListener("dragstart", onDragStart);
      window.removeEventListener(IOS_POINTER_CANCEL_ATTRACTION_EVENT, cancelAttraction);
    };
  }, []);

  return null;
}

[data-ios-pointer-attracted] {
  translate: var(--ios-pointer-attract-x, 0) var(--ios-pointer-attract-y, 0);
  scale: var(--ios-pointer-squish-x, 1) var(--ios-pointer-squish-y, 1);
}

.glass-pill-surface .glass-surface__content {
  padding: 0;
}

.liquid-glass-capsule__content {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.glass-segmented-surface,
.glass-segmented-surface .glass-surface__state,
.glass-segmented-surface .glass-surface__overlay {
  overflow: visible;
}

.glass-segmented-surface {
  box-shadow:
    0 1px 1px rgb(0 0 0 / 0.22),
    0 3px 4px -1px rgb(0 0 0 / 0.18),
    0 7px 10px -2px rgb(0 0 0 / 0.14),
    0 13px 20px -4px rgb(0 0 0 / 0.1),
    0 22px 36px -8px rgb(0 0 0 / 0.07);
}

.glass-segmented-surface .glass-surface__material {
  overflow: hidden;
}

.glass-state-chip {
  position: absolute;
  left: 0;
  top: 4px;
  height: 40px;
  border-radius: 9999px;
  overflow: hidden;
  pointer-events: none;
}

.glass-state-chip__fill,
.glass-chip-active {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: rgb(255 255 255 / 0.14);
}

.glass-segmented-drag-glass {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  pointer-events: none;
}

.glass-segmented-drag-surface {
  transition: none;
}

.glass-segmented-drag-surface.glass-surface--backdrop-blur .glass-surface__backdrop {
  backdrop-filter: blur(var(--glass-blur, 0px))
    saturate(var(--glass-segmented-drag-saturation, 1));
}

.glass-segmented-drag-surface.glass-surface--backdrop-svg .glass-surface__backdrop {
  backdrop-filter: var(--backdrop-filter-id)
    saturate(var(--glass-segmented-drag-saturation, 1));
}

.glass-segmented-drag-surface .glass-surface__lens {
  opacity: var(--glass-segmented-drag-progress, 0);
}

.glass-shell {
  background: transparent !important;
  overflow: hidden;
  isolation: isolate;
}

.glass-shell-lens {
  z-index: 1;
  overflow: hidden;
  background: transparent;
}

.glass-shell-lens-paint {
  background-color: color-mix(
    in srgb,
    var(--glass-fill, #000000) calc(var(--glass-tint, var(--glass-tint-default, 0.2)) * 100%),
    transparent
  );
}

.glass-shell-spec-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  /* Matches filter-path additive specular; normal alpha is the fallback. */
  mix-blend-mode: plus-lighter;
}

.ios-pointer-native-hover-fill {
  translate: var(--ios-pointer-attract-x, 0) var(--ios-pointer-attract-y, 0);
}

[data-ios-pointer-target],
[data-ios-pointer-target] *,
.site-hover-fill,
.site-hover-fill * {
  -webkit-user-drag: none;
  user-select: none;
}

.site-hover-fill:hover:not(.glass-segmented-item),
.site-hover-fill:focus-visible:not(.glass-segmented-item),
.site-hover-fill:active:not(.glass-segmented-item) {
  background-color: var(--fr-hover-fill, rgba(255, 255, 255, 0.06));
}

.glass-segmented-item {
  transition: color 160ms ease;
}

.glass-segmented-item:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.45);
  outline-offset: -2px;
}
